def set_cell_font(cell, text, font_size=9, bold=False, color=None):
    cell.text = text
    for paragraph in cell.paragraphs:
        for run in paragraph.runs:
            run.font.size = Pt(font_size)
            run.font.bold = bold
            run.font.name = '微软雅黑'
            if color:
                run.font.color.rgb = RGBColor(*color)


def add_heading_styled(doc, text, level=1):
    h = doc.add_heading(text, level=level)
    colors = {0: (0, 51, 102), 1: (0, 102, 204), 2: (204, 102, 0), 3: (0, 128, 64)}
    if level in colors:
        for run in h.runs:
            run.font.color.rgb = RGBColor(*colors[level])
    return h


BATCH_SIZE = 100


def add_code_block(doc, filepath, description, content, start_line=1):
    rel_path = filepath.replace(str(BASE_DIR) + os.sep, "")

    h2 = doc.add_heading(rel_path, level=2)
    for run in h2.runs:
        run.font.size = Pt(11)
        run.font.color.rgb = RGBColor(0, 51, 102)

    desc_p = doc.add_paragraph()
    r = desc_p.add_run(f"// 功能描述: {description}")
    r.font.size = Pt(9)
    r.font.color.rgb = RGBColor(106, 115, 125)
    r.font.italic = True

    lines = content.splitlines()
    for batch_start in range(0, len(lines), BATCH_SIZE):
        batch = lines[batch_start:batch_start + BATCH_SIZE]
        numbered_lines = []
        for i, line in enumerate(batch):
            lineno = start_line + batch_start + i
            safe_line = line if line else ' '
            numbered_lines.append(f"{lineno:4d}  {safe_line}")
        block_text = '\n'.join(numbered_lines)

        p = doc.add_paragraph()
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after = Pt(0)
        p.paragraph_format.line_spacing = 1.0
        run = p.add_run(block_text)
        run.font.size = Pt(8)
        run.font.name = 'Consolas'
        run.font.color.rgb = RGBColor(33, 37, 41)


