        try:
            content = full_path.read_text(encoding='utf-8', errors='ignore')
        except:
            continue
        lines = content.splitlines()
        if total_back + len(lines) > BACK_PAGES * LINES_PER_PAGE:
            remaining = BACK_PAGES * LINES_PER_PAGE - total_back
            if remaining > 0:
                content = '\n'.join(lines[:remaining])
                add_code_block(doc, fp, desc, content, cl)
                total_back += remaining
            break
        add_code_block(doc, fp, desc, content, cl)
        total_back += len(lines)
        cl += len(lines)
        doc.add_paragraph()
    
